cron.mjs.text:
// Five-field cron parsing and the "is this job late?" decision, shared by the
// browser tool and the self-hosted server. Pure functions, no I/O. UTC unless a
// schedule names an IANA zone (`tz`): the host timezone is never consulted, because
// a monitor that silently depends on it pages you at 3am twice a year.

const FIELDS = [
  { name: "minute", min: 0, max: 59 },
  { name: "hour", min: 0, max: 23 },
  { name: "dom", min: 1, max: 31 },
  { name: "month", min: 1, max: 12 },
  { name: "dow", min: 0, max: 7 },
];
const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
const MACROS = {
  "@yearly": "0 0 1 1 *", "@annually": "0 0 1 1 *", "@monthly": "0 0 1 * *",
  "@weekly": "0 0 * * 0", "@daily": "0 0 * * *", "@midnight": "0 0 * * *", "@hourly": "0 * * * *",
};

function toNumber(token, idx) {
  const lower = token.toLowerCase();
  if (idx === 3 && MONTHS.includes(lower)) return MONTHS.indexOf(lower) + 1;
  if (idx === 4 && DAYS.includes(lower)) return DAYS.indexOf(lower);
  if (!/^\d+$/.test(token)) throw new Error(`"${token}" is not a number in the ${FIELDS[idx].name} field`);
  return Number(token);
}

function parseField(text, idx) {
  const { min, max, name } = FIELDS[idx];
  const values = new Set();
  for (const part of text.split(",")) {
    if (part === "") throw new Error(`empty item in the ${name} field`);
    const [range, stepText, extra] = part.split("/");
    if (extra !== undefined) throw new Error(`too many "/" in the ${name} field`);
    let step = 1;
    if (stepText !== undefined) {
      if (!/^\d+$/.test(stepText) || Number(stepText) < 1) throw new Error(`bad step "${stepText}" in the ${name} field`);
      step = Number(stepText);
    }
    let lo, hi;
    if (range === "*") { lo = min; hi = idx === 4 ? 6 : max; }
    else if (range.includes("-")) {
      const [a, b, more] = range.split("-");
      if (more !== undefined) throw new Error(`bad range "${range}" in the ${name} field`);
      lo = toNumber(a, idx); hi = toNumber(b, idx);
    } else {
      lo = toNumber(range, idx);
      hi = stepText !== undefined ? (idx === 4 ? 6 : max) : lo;
    }
    if (lo < min || hi > max || lo > hi) throw new Error(`${range} is outside ${min}-${max} in the ${name} field`);
    for (let v = lo; v <= hi; v += step) values.add(idx === 4 && v === 7 ? 0 : v);
  }
  return values;
}

const fmtCache = new Map();
function formatter(tz) {
  let f = fmtCache.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", { timeZone: tz, hourCycle: "h23", year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "numeric", weekday: "short" });
    fmtCache.set(tz, f);
  }
  return f;
}

/** Throws on an unknown IANA zone name; returns the name. */
export function checkTimezone(tz) {
  if (typeof tz !== "string" || !tz || tz.length > 64) throw new Error("timezone must be an IANA name such as Europe/London");
  try { formatter(tz); } catch { throw new Error(`unknown timezone "${tz}": use an IANA name such as Europe/London`); }
  return tz;
}

/** Wall-clock fields of an instant (ms) in `tz`. */
export function localParts(ms, tz) {
  const o = {};
  for (const p of formatter(tz).formatToParts(new Date(ms))) o[p.type] = p.value;
  return { month: Number(o.month), day: Number(o.day), hour: Number(o.hour), minute: Number(o.minute), dow: DAYS.indexOf(o.weekday.toLowerCase()), key: `${o.year}-${o.month}-${o.day} ${o.hour}:${o.minute}` };
}

export function parseCron(expression, tz) {
  if (typeof expression !== "string") throw new Error("cron expression must be text");
  let text = expression.trim().replace(/\s+/g, " ");
  if (MACROS[text.toLowerCase()]) text = MACROS[text.toLowerCase()];
  if (text.startsWith("@")) throw new Error(`unsupported macro ${text} (@reboot cannot be scheduled)`);
  const parts = text.split(" ");
  if (parts.length !== 5) throw new Error(`expected 5 fields (minute hour day-of-month month day-of-week), got ${parts.length}`);
  const sets = parts.map((p, i) => parseField(p, i));
  return {
    minute: sets[0], hour: sets[1], dom: sets[2], month: sets[3], dow: sets[4],
    domStar: parts[2].startsWith("*"), dowStar: parts[4].startsWith("*"),
    text,
    tz: tz && tz.toUpperCase() !== "UTC" ? checkTimezone(tz) : null,
  };
}

function matches(c, d) {
  if (!c.minute.has(d.getUTCMinutes()) || !c.hour.has(d.getUTCHours()) || !c.month.has(d.getUTCMonth() + 1)) return false;
  const domOk = c.dom.has(d.getUTCDate());
  const dowOk = c.dow.has(d.getUTCDay());
  // Vixie cron: when both day fields are restricted, either one may match.
  if (!c.domStar && !c.dowStar) return domOk || dowOk;
  return domOk && dowOk;
}

function dayOk(c, p) {
  return (!c.domStar && !c.dowStar) ? (c.dom.has(p.day) || c.dow.has(p.dow)) : (c.dom.has(p.day) && c.dow.has(p.dow));
}

// Zoned search. Steps by instants and reads the wall clock, so DST needs no special
// casing in the stepping. Two DST rules, same as Vixie cron:
//  - fall back: a wall time that happens twice counts once (the job runs once);
//  - spring forward: a wall time that does not exist is skipped that day.
function nextRunZoned(c, after) {
  let t = Math.floor(after / 60000) * 60000 + 60000;
  const limit = after + 5 * 366 * 86400000;
  while (t <= limit) {
    const p = localParts(t, c.tz);
    if (!c.month.has(p.month) || !dayOk(c, p)) { t += Math.max(30, (24 - p.hour) * 60 - p.minute - 30) * 60000; continue; }
    if (!c.hour.has(p.hour)) { t += (60 - p.minute) * 60000; continue; }
    if (!c.minute.has(p.minute)) { t += 60000; continue; }
    const repeat = [30, 60, 120].some((m) => localParts(t - m * 60000, c.tz).key === p.key);
    if (!repeat) return new Date(t);
    t += 60000;
  }
  return null;
}

/** The first scheduled minute strictly after `after` (a Date), or null within 5 years. */
export function nextRun(cron, after, tz) {
  const c = typeof cron === "string" ? parseCron(cron, tz) : cron;
  if (c.tz) return nextRunZoned(c, after.getTime());
  const d = new Date(Math.floor(after.getTime() / 60000) * 60000 + 60000);
  const limit = after.getTime() + 5 * 366 * 86400000;
  while (d.getTime() <= limit) {
    if (!c.month.has(d.getUTCMonth() + 1)) { d.setUTCMonth(d.getUTCMonth() + 1, 1); d.setUTCHours(0, 0, 0, 0); continue; }
    const dayOk = (!c.domStar && !c.dowStar) ? (c.dom.has(d.getUTCDate()) || c.dow.has(d.getUTCDay()))
      : (c.dom.has(d.getUTCDate()) && c.dow.has(d.getUTCDay()));
    if (!dayOk) { d.setUTCDate(d.getUTCDate() + 1); d.setUTCHours(0, 0, 0, 0); continue; }
    if (!c.hour.has(d.getUTCHours())) { d.setUTCHours(d.getUTCHours() + 1, 0, 0, 0); continue; }
    if (!c.minute.has(d.getUTCMinutes())) { d.setUTCMinutes(d.getUTCMinutes() + 1, 0, 0); continue; }
    if (matches(c, d)) return new Date(d.getTime());
    d.setUTCMinutes(d.getUTCMinutes() + 1);
  }
  return null;
}

export function nextRuns(cron, after, count = 5, tz) {
  const c = typeof cron === "string" ? parseCron(cron, tz) : cron;
  const out = [];
  let cursor = after;
  while (out.length < count) {
    const n = nextRun(c, cursor);
    if (!n) break;
    out.push(n);
    cursor = n;
  }
  return out;
}

/** Typical gap between runs in seconds (median of the next 8 gaps). */
export function typicalIntervalSeconds(cron, from, tz) {
  const runs = nextRuns(cron, from, 9, tz);
  if (runs.length < 2) return null;
  const gaps = runs.slice(1).map((r, i) => (r - runs[i]) / 1000).sort((a, b) => a - b);
  return gaps[Math.floor(gaps.length / 2)];
}

/** Largest gap among the next 12 runs: the longest silence that is still healthy. */
export function longestGapSeconds(cron, from, tz) {
  const runs = nextRuns(cron, from, 13, tz);
  if (runs.length < 2) return null;
  return Math.max(...runs.slice(1).map((r, i) => (r - runs[i]) / 1000));
}

/** A grace period that tolerates normal jitter without hiding a missed run: 10% of the interval, 1 min to 1 h. */
export function suggestGraceSeconds(cron, from, tz) {
  const gap = typicalIntervalSeconds(cron, from, tz);
  if (gap === null) return 300;
  return Math.max(60, Math.min(3600, Math.round(gap * 0.1 / 60) * 60 || 60));
}

/**
 * Decide a check's state at `now`.
 * check: { schedule?: cron text, tz?: IANA zone, periodSeconds?: number, graceSeconds, lastPing?: ms, lastStart?: ms, lastFail?: ms, createdAt: ms, paused?: bool }
 * Returns { state: "new"|"up"|"late"|"down"|"running"|"failed"|"paused", dueAt: ms|null, reason }.
 */
export function evaluate(check, now) {
  const grace = (check.graceSeconds ?? 300) * 1000;
  if (check.paused) return { state: "paused", dueAt: null, reason: "paused" };
  if (check.lastFail && check.lastFail >= (check.lastPing ?? 0)) {
    return { state: "failed", dueAt: null, reason: "the job reported a failure" };
  }
  const base = check.lastPing ?? check.createdAt;
  let dueAt;
  if (check.schedule) {
    dueAt = nextRun(check.schedule, new Date(base), check.tz)?.getTime() ?? null;
  } else if (check.periodSeconds) {
    dueAt = base + check.periodSeconds * 1000;
  } else {
    return { state: "new", dueAt: null, reason: "no schedule or period set" };
  }
  if (dueAt === null) return { state: "new", dueAt: null, reason: "schedule never fires" };
  if (check.lastStart && check.lastStart > (check.lastPing ?? 0) && now <= dueAt + grace) {
    return { state: "running", dueAt, reason: "started, not finished" };
  }
  if (now <= dueAt) return { state: check.lastPing ? "up" : "new", dueAt, reason: "waiting for the next run" };
  if (now <= dueAt + grace) return { state: "late", dueAt, reason: "past due, inside the grace period" };
  return { state: "down", dueAt, reason: `no ping ${Math.round((now - dueAt) / 1000)}s after it was due` };
}

export function formatDuration(seconds) {
  const s = Math.round(seconds);
  if (s < 90) return `${s}s`;
  if (s < 5400) return `${Math.round(s / 60)} min`;
  if (s < 129600) return `${Math.round(s / 3600 * 10) / 10} h`;
  return `${Math.round(s / 86400 * 10) / 10} days`;
}

crontab.mjs.text:
// Turns pasted crontab text into monitor entries: validity, next runs, the
// longest healthy silence, a suggested grace period, a wrapped command line
// and the checks.json the self-hosted server reads.
import { checkTimezone, parseCron, nextRuns, longestGapSeconds, suggestGraceSeconds, formatDuration } from "./cron.mjs";

const MACRO_RE = /^@[a-z]+$/i;

export function slugify(command, taken) {
  const segments = command.split(/&&|;/).map((x) => x.trim()).filter(Boolean);
  const words = (segments[segments.length - 1] || command).replace(/[>|&<].*$/, "").split(/\s+/).filter(Boolean);
  const pick = words.find((w) => /[a-z]/i.test(w) && !/^(sudo|nice|ionice|flock|\/usr\/bin\/env|env|cd|bash|sh|-.*)$/i.test(w) && !/^\w+=/.test(w)) || "job";
  let base = pick.split("/").pop().replace(/\.[a-z0-9]+$/i, "").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "job";
  if (!/^[a-z0-9]/.test(base)) base = `job-${base}`;
  let slug = base, n = 2;
  while (taken.has(slug)) slug = `${base}-${n++}`;
  taken.add(slug);
  return slug;
}

export function splitLine(line) {
  const t = line.trim();
  if (MACRO_RE.test(t.split(/\s+/)[0])) {
    const [schedule, ...rest] = t.split(/\s+/);
    return { schedule, command: rest.join(" ") };
  }
  const parts = t.split(/\s+/);
  return { schedule: parts.slice(0, 5).join(" "), command: parts.slice(5).join(" ") };
}

export function wrapCommand(command, pingUrl) {
  const curl = `curl -fsS -m 10 --retry 3 -o /dev/null ${pingUrl}`;
  return `${command} && ${curl} || ${curl}/fail`;
}

export function analyzeCrontab(text, now, baseUrl = "https://monitor.example.com") {
  const entries = [], taken = new Set();
  let tz = null; // CRON_TZ= (cronie, Vixie) applies to the lines below it
  const lines = String(text || "").split(/\r?\n/);
  lines.forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const zone = line.match(/^CRON_TZ\s*=\s*["']?([^"'\s]*)["']?$/);
    if (zone) {
      try { tz = zone[1] ? checkTimezone(zone[1]) : null; } catch (e) { entries.push({ line: i + 1, schedule: line, command: "", error: e.message }); tz = null; }
      return;
    }
    if (/^[A-Za-z_][A-Za-z0-9_]*\s*=/.test(line)) return; // MAILTO=, PATH=, ...
    const { schedule, command } = splitLine(line);
    const entry = { line: i + 1, schedule, command, tz };
    try {
      const cron = parseCron(schedule, tz);
      if (!command) throw new Error("no command after the schedule");
      entry.slug = slugify(command, taken);
      entry.nextRuns = nextRuns(cron, now, 5);
      entry.longestGapSeconds = longestGapSeconds(cron, now);
      entry.graceSeconds = suggestGraceSeconds(cron, now);
      entry.longestGapText = formatDuration(entry.longestGapSeconds);
      entry.graceText = formatDuration(entry.graceSeconds);
      entry.pingUrl = `${baseUrl.replace(/\/$/, "")}/ping/${entry.slug}`;
      entry.wrapped = `${schedule} ${wrapCommand(command, entry.pingUrl)}`;
      entry.warnings = warn(cron, entry);
    } catch (e) {
      entry.error = e.message;
    }
    entries.push(entry);
  });
  const ok = entries.filter((e) => !e.error);
  const config = Object.fromEntries(ok.map((e) => [e.slug, { schedule: e.schedule, ...(e.tz ? { tz: e.tz } : {}), graceSeconds: e.graceSeconds }]));
  return { entries, config, configJson: JSON.stringify(config, null, 2) };
}

function warn(cron, entry) {
  const w = [];
  if (/(^|\s)\*\/?\d*\s+\*\s+\*\s+\*\s+\*/.test(entry.schedule) && entry.longestGapSeconds <= 60) w.push("Runs every minute: a 1-minute grace will page you on ordinary scheduler jitter. Consider a longer grace or a heartbeat on a coarser cadence.");
  if (entry.longestGapSeconds > 7 * 86400) w.push(`Longest gap is ${entry.longestGapText}: confirm that is intended, and set a grace period that fits the job's duration.`);
  if (/>\s*\/dev\/null\s*2>&1\s*$/.test(entry.command) && !/&&|\|\|/.test(entry.command)) w.push("Output is discarded, so failures are silent today. The wrapped line below reports exit status instead of hiding it.");
  if (!cron.domStar && !cron.dowStar) w.push("Both day-of-month and day-of-week are set: cron runs on either match, not both.");
  return w;
}

dashboard.mjs.text:
// HTML for the dashboard (private, needs the key) and the public status page.
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const COLOR = { up: "#1a7f37", running: "#0969da", late: "#9a6700", new: "#6e7781", paused: "#6e7781", down: "#cf222e", failed: "#cf222e" };
const ago = (ms, now) => {
  if (ms == null) return "never";
  const s = Math.max(0, Math.round((now - ms) / 1000));
  return s < 90 ? `${s}s ago` : s < 5400 ? `${Math.round(s / 60)}m ago` : s < 129600 ? `${Math.round(s / 3600)}h ago` : `${Math.round(s / 86400)}d ago`;
};
const page = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:46rem;margin:2rem auto;padding:0 1rem;color:#1f2328;background:#fff}@media(prefers-color-scheme:dark){body{background:#0d1117;color:#e6edf3}td,th{border-color:#30363d!important}}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:.5rem;border-bottom:1px solid #d0d7de}.dot{display:inline-block;width:.7rem;height:.7rem;border-radius:50%;margin-right:.4rem}small{opacity:.7}</style></head><body>${body}</body></html>`;

export function dashboardHtml(rows, now, { channels = [] } = {}) {
  const bad = rows.filter((r) => r.state === "down" || r.state === "failed").length;
  const trs = rows.map((r) => `<tr><td><span class="dot" style="background:${COLOR[r.state] || "#6e7781"}"></span><b>${esc(r.slug)}</b></td><td>${esc(r.state)}<br><small>${esc(r.reason)}</small></td><td>${esc(ago(r.lastPing, now))}<br><small>${r.pings} pings</small></td></tr>`).join("");
  return page("cron-heartbeat", `<h1>cron-heartbeat</h1><p>${bad ? `<b style="color:#cf222e">${bad} check${bad > 1 ? "s" : ""} need attention.</b>` : "All checks healthy."} <small>Alerts: ${channels.length ? esc(channels.join(", ")) : "none configured (set one in the environment)"}</small></p><table><tr><th>Check</th><th>State</th><th>Last ping</th></tr>${trs || '<tr><td colspan="3">No checks configured.</td></tr>'}</table>`);
}

/** Public page: names and up/down only, never reasons, keys or timings. */
export function publicStatusHtml(rows, title = "Status") {
  const bad = rows.filter((r) => r.state === "down" || r.state === "failed").length;
  const trs = rows.map((r) => { const ok = r.state !== "down" && r.state !== "failed"; return `<tr><td><span class="dot" style="background:${ok ? COLOR.up : COLOR.down}"></span>${esc(r.slug)}</td><td>${ok ? "Operational" : "Disruption"}</td></tr>`; }).join("");
  return page(title, `<h1>${esc(title)}</h1><p><b>${bad ? "Some systems are having problems." : "All systems operational."}</b></p><table>${trs}</table>`);
}

/** Shields-style SVG badge for one check: name + Operational/Disruption/Paused. Same disclosure as /s. */
export function badgeSvg(slug, state) {
  const bad = state === "down" || state === "failed";
  const label = bad ? "disruption" : state === "paused" ? "paused" : "operational";
  const color = bad ? COLOR.down : state === "paused" ? COLOR.paused : COLOR.up;
  const w1 = 12 + slug.length * 7, w2 = 12 + label.length * 7, w = w1 + w2;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="20" role="img" aria-label="${esc(slug)}: ${label}"><rect width="${w1}" height="20" fill="#555"/><rect x="${w1}" width="${w2}" height="20" fill="${color}"/><g fill="#fff" font-family="Verdana,sans-serif" font-size="11" text-anchor="middle"><text x="${w1 / 2}" y="14">${esc(slug)}</text><text x="${w1 + w2 / 2}" y="14">${label}</text></g></svg>`;
}

monitor.mjs.text:
// Heartbeat monitor core: config + persisted state in, alerts out. Separate from
// the HTTP shell (server.mjs) so the alert rules are testable without sockets.
import { evaluate, parseCron, checkTimezone } from "./cron.mjs";

const HISTORY_MAX = 50;
const SLUG = /^[a-z0-9][a-z0-9_-]{0,63}$/;

export function validateConfig(config) {
  if (!config || typeof config !== "object" || Array.isArray(config)) throw new Error("config must be an object of slug -> check");
  const out = {};
  for (const [slug, raw] of Object.entries(config)) {
    if (!SLUG.test(slug)) throw new Error(`bad check name "${slug}": use lowercase letters, digits, - and _`);
    const c = raw || {};
    if (!c.schedule && !c.periodSeconds) throw new Error(`${slug}: set "schedule" (cron) or "periodSeconds"`);
    if (c.tz !== undefined && !c.schedule) throw new Error(`${slug}: "tz" only applies to a cron "schedule"`);
    if (c.schedule) parseCron(c.schedule, c.tz);
    if (c.periodSeconds !== undefined && !(Number(c.periodSeconds) >= 10)) throw new Error(`${slug}: periodSeconds must be at least 10`);
    if (c.graceSeconds !== undefined && !(Number(c.graceSeconds) >= 0)) throw new Error(`${slug}: graceSeconds must be 0 or more`);
    out[slug] = {
      schedule: c.schedule || null,
      tz: c.tz && String(c.tz).toUpperCase() !== "UTC" ? checkTimezone(c.tz) : null,
      periodSeconds: c.periodSeconds ? Number(c.periodSeconds) : null,
      graceSeconds: c.graceSeconds !== undefined ? Number(c.graceSeconds) : 300,
      paused: Boolean(c.paused),
    };
  }
  return out;
}

export function createMonitor({ config, state = {}, notify = async () => {} }) {
  const checks = validateConfig(config);
  const st = state;
  const view = (slug, now) => {
    const rec = st[slug] || {};
    return { ...checks[slug], paused: rec.paused ?? checks[slug].paused, createdAt: rec.createdAt ?? now, lastPing: rec.lastPing, lastStart: rec.lastStart, lastFail: rec.lastFail };
  };

  function ensure(slug, now) {
    if (!st[slug]) st[slug] = { createdAt: now, lastAlert: "new", pings: 0 };
    return st[slug];
  }

  /** kind: "success" | "start" | "fail". Returns false for an unknown check. */
  function ping(slug, kind, now) {
    if (!checks[slug]) return false;
    const rec = ensure(slug, now);
    const h = (rec.history ||= []);
    h.push({ t: now, kind });
    if (h.length > HISTORY_MAX) h.splice(0, h.length - HISTORY_MAX);
    if (kind === "start") rec.lastStart = now;
    else if (kind === "fail") rec.lastFail = now;
    else { rec.lastPing = now; rec.pings = (rec.pings || 0) + 1; }
    return true;
  }

  /** Pause or resume one check at runtime (maintenance window). Returns false for an unknown check.
   * Resuming restarts the clock, so a long pause never raises an alert for the time it was off. */
  function setPaused(slug, paused, now) {
    if (!checks[slug]) return false;
    const rec = ensure(slug, now);
    rec.paused = Boolean(paused);
    if (!paused) { rec.createdAt = now; delete rec.lastPing; delete rec.lastStart; delete rec.lastFail; rec.lastAlert = "new"; }
    const h = (rec.history ||= []);
    h.push({ t: now, kind: paused ? "paused" : "resumed" });
    if (h.length > HISTORY_MAX) h.splice(0, h.length - HISTORY_MAX);
    return true;
  }

  function logEvent(rec, now, kind) {
    const h = (rec.history ||= []);
    h.push({ t: now, kind: `alert:${kind}` });
    if (h.length > HISTORY_MAX) h.splice(0, h.length - HISTORY_MAX);
  }

  /** Recent pings and alerts for one check, newest first; null for an unknown check. */
  function history(slug) {
    if (!checks[slug]) return null;
    return [...((st[slug] || {}).history || [])].reverse();
  }

  async function tick(now) {
    const sent = [];
    for (const slug of Object.keys(checks)) {
      const rec = ensure(slug, now);
      const r = evaluate(view(slug, now), now);
      const bad = r.state === "down" || r.state === "failed";
      const wasBad = rec.lastAlert === "down" || rec.lastAlert === "failed";
      if (bad && rec.lastAlert !== r.state) {
        const msg = { slug, state: r.state, text: `[cron-heartbeat] ${slug} is ${r.state.toUpperCase()}: ${r.reason}`, at: now };
        sent.push(msg); rec.lastAlert = r.state; logEvent(rec, now, r.state);
        try { await notify(msg); } catch (e) { rec.lastAlert = "new"; rec.notifyError = String(e.message || e); }
      } else if (!bad && wasBad && (r.state === "up" || r.state === "running" || r.state === "late")) {
        const msg = { slug, state: "recovered", text: `[cron-heartbeat] ${slug} recovered`, at: now };
        sent.push(msg); rec.lastAlert = "up"; logEvent(rec, now, "recovered");
        try { await notify(msg); } catch (e) { rec.notifyError = String(e.message || e); }
      } else if (!bad) rec.lastAlert = rec.lastAlert === "new" && r.state === "new" ? "new" : r.state;
    }
    return sent;
  }

  function status(now) {
    return Object.keys(checks).map((slug) => {
      const r = evaluate(view(slug, now), now);
      const rec = st[slug] || {};
      return { slug, state: r.state, reason: r.reason, dueAt: r.dueAt, lastPing: rec.lastPing ?? null, pings: rec.pings || 0 };
    });
  }

  return { ping, setPaused, tick, status, history, state: st, checks };
}

